    try: t=open(f).read()
    except: return []
    return [path(x) for x in re.findall(r'^import (AlgebraicJacobian[\w.]*)',t,re.M)]
def cone(start):
    seen=set(); q=deque([start])
    while q:
        f=q.popleft()
        if f in seen: continue
        seen.add(f)
        for i in imports(f): q.append(i)
    return seen
